mapper.select:
SELECT schedule_seq
FROM wishlist
WHERE member_id = #{memberId}

mapper.insert:
INSERT INTO wishlist (wishlist_seq, member_id, schedule_seq)
VALUES (
    (
        SELECT COALESCE(MAX(wishlist_seq), 0) + 1
        FROM wishlist
    ),
    #{memberId},
    #{scheduleSeq}
)

mapper.delete:
DELETE FROM wishlist
WHERE member_id = #{memberId}
  AND schedule_seq = #{scheduleSeq}
